// ==================== CONFIG ====================
const config = {
    cellSize: 15,
    updateRate: 5,   // Frame skip (lower = faster)
    trailFade: 0.1,  // How fast dead cells dim
    color: {r: 0, g: 255, b: 0} // Hacker Green
};

// ==================== STATE ====================
if (state.grid === undefined) {
    state.cols = Math.ceil(width / config.cellSize);
    state.rows = Math.ceil(height / config.cellSize);
    state.grid = [];
    state.nextGrid = []; // Buffer
    state.frameTimer = 0;

    // Initialize random grid
    for(let i=0; i<state.cols * state.rows; i++) {
        // value 0.0 to 1.0 (0=dead, 1=alive)
        // Initialize with boolean logic for "Alive"
        state.grid[i] = Math.random() > 0.8 ? 1.0 : 0.0;
        state.nextGrid[i] = 0.0;
    }
}

// ==================== DRAW ====================
// Background
ctx.fillStyle(0, 5, 0, 255);
ctx.fillRect(0, 0, width, height);

// Logic Update (throttled)
state.frameTimer++;
let update = state.frameTimer % config.updateRate === 0;

if (update) {
    // Perform Game of Life rules
    for(let y=0; y<state.rows; y++) {
        for(let x=0; x<state.cols; x++) {
            let i = y * state.cols + x;

            // Count Neighbors
            let neighbors = 0;
            for(let dy=-1; dy<=1; dy++) {
                for(let dx=-1; dx<=1; dx++) {
                    if (dx===0 && dy===0) continue;

                    // Wrap coordinates
                    let nx = (x + dx + state.cols) % state.cols;
                    let ny = (y + dy + state.rows) % state.rows;

                    // Check if neighbor is "alive" (value > 0.9)
                    if (state.grid[ny * state.cols + nx] > 0.9) neighbors++;
                }
            }

            let isAlive = state.grid[i] > 0.9;
            let result = isAlive;

            // Rules
            if (isAlive && (neighbors < 2 || neighbors > 3)) result = false;
            else if (!isAlive && neighbors === 3) result = true;

            // Write to buffer (1.0 for alive, decay existing value if dead)
            if (result) {
                state.nextGrid[i] = 1.0;
            } else {
                if (isAlive) state.nextGrid[i] = 0.9; 
                else state.nextGrid[i] = Math.max(0, state.grid[i] - config.trailFade);
            }
        }
    }

    // Swap buffers
    let temp = state.grid;
    state.grid = state.nextGrid;
    state.nextGrid = temp;
}

// Render Grid
for(let y=0; y<state.rows; y++) {
    for(let x=0; x<state.cols; x++) {
        let val = state.grid[y * state.cols + x];

        if (val > 0.05) {
            let px = x * config.cellSize;
            let py = y * config.cellSize;

            // Alive cells are bright, trails are dim
            let alpha = Math.floor(255 * val);

            // If fully alive, use white center
            if (val > 0.95) {
                ctx.fillStyle(config.color.r, config.color.g, config.color.b, 255);
                ctx.fillRect(px, py, config.cellSize - 1, config.cellSize - 1);

                // Center dot
                ctx.fillStyle(255, 255, 255, 200);
                ctx.fillRect(px + 4, py + 4, config.cellSize - 8, config.cellSize - 8);
            } else {
                // Fading trail
                ctx.fillStyle(config.color.r, config.color.g, config.color.b, alpha);
                ctx.fillRect(px, py, config.cellSize - 1, config.cellSize - 1);
            }
        }
    }
}

// Mouse interaction (Simulated)
// Add random life if audio peaks
if (audio.IsEnabled && audio.Bass > 0.8) {
    let rx = Math.floor(Math.random() * state.cols);
    let ry = Math.floor(Math.random() * state.rows);
    state.grid[ry * state.cols + rx] = 1.0;
}
